import{_ as e,a0 as l,w as s,s as n,I as a,x as r,a1 as o,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何安装树莓派摄像头模块 | LCTT x X-CMD","titleTemplate":false,"description":"如何安装树莓派摄像头模块 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安装树莓派摄像头模块 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安装树莓派摄像头模块 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140702 How to install Raspberry Pi camera board","title":"如何安装树莓派摄像头模块","tag":"201408","desc":""},"relativePath":"201408/20140702 How to install Raspberry Pi camera board.md","filePath":"[post].md"}'),m={name:"201408/20140702 How to install Raspberry Pi camera board.md"},u={id:"kristophorus-hadiono",tabindex:"-1"};function f(b,t,g,h,x,y){const p=l("Link");return s(),n("div",null,[t[23]||(t[23]=a("h1",{id:"如何安装树莓派摄像头模块",tabindex:"-1"},[r("如何安装树莓派摄像头模块 "),a("a",{class:"header-anchor",href:"#如何安装树莓派摄像头模块","aria-label":"Permalink to “如何安装树莓派摄像头模块”"},"​")],-1)),a("p",null,[o(p,{href:"http://xmodulo.com/go/picam"},{default:i(()=>[...t[0]||(t[0]=[r("树莓派摄像头模块(Pi Cam)",-1)])]),_:1}),t[2]||(t[2]=r("发售于2013年5月。其第一个发布版本配备了500万像素的传感器，通过排线链接树莓派上的CSI接口。而Pi Cam的第二个发布版本——也被叫做",-1)),o(p,{href:"http://xmodulo.com/go/pinoir"},{default:i(()=>[...t[1]||(t[1]=[r("Pi NoIR",-1)])]),_:1}),t[3]||(t[3]=r("中，配备了相同的传感器，但没有红外线过滤装置。因此第二版的摄像头模块就像安全监控摄像机一样，可以观测到近红外线的波长(700 - 1000 nm)，不过当然同时也就牺牲了一定的显色性。",-1))]),a("p",null,[t[7]||(t[7]=r("本文将会展示",-1)),a("strong",null,[t[5]||(t[5]=r("如何在",-1)),o(p,{href:"http://xmodulo.com/go/raspberrypi"},{default:i(()=>[...t[4]||(t[4]=[r("树莓派",-1)])]),_:1}),t[6]||(t[6]=r("上安装摄像头模块",-1))]),t[8]||(t[8]=r("。我们将使用第一版摄像头模块来演示。在安装完摄像头模块之后，你将会使用三个应用程序来访问这个模块：raspistill, raspiyuv 和raspivid。其中前两个应用用来捕捉图像，第三个应用来捕捉视频。raspistill 工具生成标准的图片文件，例如 .jpg 图像，而 raspiyuv 可以通过摄像头生成未处理的 raw 图像文件。",-1))]),t[24]||(t[24]=d(`<h3 id="安装树莓派摄像头模块" tabindex="-1">安装树莓派摄像头模块 <a class="header-anchor" href="#安装树莓派摄像头模块" aria-label="Permalink to “安装树莓派摄像头模块”">​</a></h3><p>按照以下步骤来将树莓派摄像头模块连接搭配树莓派：</p><ol><li><p>找到 CSI 接口(CSI接口在以太网接口旁边)，掀起深色胶带。</p></li><li><p>拉起 CSI 接口挡板。</p></li><li><p>拿起你的摄像头模块，将贴在镜头上的塑料保护膜撕掉。确保黄色部分的PCB(有字的一面)是安装完美的（可以轻轻按一下黄色的部分来保证安装完美）。</p></li><li><p>将排线插入CSI接口。记住，有蓝色胶带的一面应该面向以太网接口方向。同样，这时也确认一下排线安装好了之后，将挡板拉下。</p></li></ol><p><img src="https://farm3.staticflickr.com/2938/14529915452_0910b2e13f_z.jpg" alt=""></p><p>好了，现在你的 Pi Cam 已经准备就绪，可以拍摄照片或视频了。</p><h3 id="在树莓派上启用摄像头模块" tabindex="-1">在树莓派上启用摄像头模块 <a class="header-anchor" href="#在树莓派上启用摄像头模块" aria-label="Permalink to “在树莓派上启用摄像头模块”">​</a></h3><p>在安装完摄像头模块之后，首先要确认你已经升级了树莓派系统并应用了最新的固件。可以输入以下命令来操作：</p><pre><code>$ sudo apt-get update
$ sudo apt-get upgrade 
</code></pre><p>运行树莓派配置工具来激活摄像头模块：</p><pre><code>$ sudo raspi-config 
</code></pre><p>移动光标至菜单中的 &quot;Enable Camera（启用摄像头）&quot;，将其设为Enable（启用状态）。完成之后重启树莓派。</p><p><img src="https://farm4.staticflickr.com/3837/14530918915_e68ca0beef_z.jpg" alt=""></p><p><img src="https://farm3.staticflickr.com/2922/14344284230_6cabbe2522_z.jpg" alt=""></p><p><img src="https://farm3.staticflickr.com/2923/14529915362_7a437a53cb_z.jpg" alt=""></p><p>安装完摄像头模块后的完成照：</p><p><img src="https://farm3.staticflickr.com/2924/14551046653_1c37e077fd_z.jpg" alt=""></p><h3 id="通过摄像头模块拍照" tabindex="-1">通过摄像头模块拍照 <a class="header-anchor" href="#通过摄像头模块拍照" aria-label="Permalink to “通过摄像头模块拍照”">​</a></h3><p>在重启完树莓派后，我们就可以使用Pi Cam了。要用它来拍摄照片的话，可以从命令行运行raspistill：</p><pre><code>$ raspistill -o keychain.jpg -t 2000 
</code></pre><p>这句命令将在 2000ms 后拍摄一张照片，然后保存为 keychain.jpg。下面就是一张由 Pi Cam 拍摄的我的小熊公仔钥匙链。</p><p><img src="https://farm4.staticflickr.com/3845/14530919095_ea0f37045a_z.jpg" alt=""></p><p>raspiyuv 工具用法差不多，只不过拍摄得到的是一张未处理过的raw图像。</p><h3 id="通过摄像头模块拍视频" tabindex="-1">通过摄像头模块拍视频 <a class="header-anchor" href="#通过摄像头模块拍视频" aria-label="Permalink to “通过摄像头模块拍视频”">​</a></h3><p>想要用摄像头模块拍一段视频的话，可以从命令行运行 raspivid 工具。下面这句命令会按照默认配置(长度5秒，分辨率1920x1080，比特率 17Mbps)拍摄一段视频。</p><pre><code>$ raspivid -o mykeychain.h264
</code></pre><p>如果你想改变拍摄时长，只要通过 &quot;-t&quot; 选项来设置你想要的长度就行了（单位是毫秒）。</p><pre><code>$ raspivid -o mykeychain.h264 -t 10000
</code></pre><p>使用 &quot;-w&quot; 和 &quot;-h&quot; 选项将分辨率降为 1280x720...</p><pre><code>$ raspivid -o mykeychain.h264 -t 10000 -w 1280 -h 720
</code></pre><p>raspivid 的输出是一段未压缩的 H.264 视频流，而且这段视频不含声音。为了能被通常的视频播放器所播放，这个 raw 的 H.264 视频还需要转换。可以使用 gpac 包中所带有的 MP4Box 应用。</p><p>在 Raspbian 上安装 gpac，输入命令：</p><pre><code>$ sudo apt-get install -y gpac 
</code></pre><p>然后将这段 raw 的 H.264 格式的视频流转换为每秒30帧的 .mp4 格式视频：</p><pre><code>$ MP4Box -fps 30 -add keychain.h264 keychain.mp4 
</code></pre><p>视频长度为10秒，使用默认分辨率以及比特率。下面是一段通过 Pi Camera 拍摄的一段实例视频。</p><p>注：youtube视频地址</p>`,36)),t[25]||(t[25]=a("iframe",{width:"615",height:"376",frameborder:"0",src:"http://www.youtube.com/embed/3uyR2AVVwAU?version=3&rel=1&fs=1&showsearch=0&showinfo=1&iv_load_policy=1&wmode=transparent",type:"text/html",class:"youtube-player"},null,-1)),t[26]||(t[26]=a("p",null,"如果想要获取 raspistill, raspiyuv 和 raspivid 的完整命令行选项，不加任何选项直接运行以上命令即可。",-1)),t[27]||(t[27]=a("hr",null,null,-1)),a("h3",u,[o(p,{href:"http://hadiono.org/blog"},{default:i(()=>[...t[9]||(t[9]=[r("Kristophorus Hadiono",-1)])]),_:1}),t[10]||(t[10]=r()),t[11]||(t[11]=a("a",{class:"header-anchor",href:"#kristophorus-hadiono","aria-label":"Permalink to “Kristophorus Hadiono”"},"​",-1))]),t[28]||(t[28]=a("p",null,"Kristophorus Hadiono是一名 Linux 爱好者，并且是印度尼西亚一所民办高等学府的教师。他在日常生活中使用 Linux，也在给学生们教学的时候使用。他现在仍靠着政府的奖学金，在泰国曼谷的一所民办大学继续着学业。",-1)),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[13]||(t[13]=r("via: ",-1)),o(p,{href:"http://xmodulo.com/2014/07/install-raspberry-pi-camera-board.html"},{default:i(()=>[...t[12]||(t[12]=[r("http://xmodulo.com/2014/07/install-raspberry-pi-camera-board.html",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=r("译者：",-1)),o(p,{href:"https://github.com/ThomazL"},{default:i(()=>[...t[14]||(t[14]=[r("ThomazL",-1)])]),_:1}),t[17]||(t[17]=r(" 校对：",-1)),o(p,{href:"https://github.com/reinoir"},{default:i(()=>[...t[15]||(t[15]=[r("reinoir",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=r("本文由 ",-1)),o(p,{href:"https://github.com/lctt/translateproject"},{default:i(()=>[...t[18]||(t[18]=[r("lctt",-1)])]),_:1}),t[21]||(t[21]=r(" 原创翻译，",-1)),o(p,{href:"http://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[r("linux中国",-1)])]),_:1}),t[22]||(t[22]=r(" 荣誉推出",-1))])])}const w=e(m,[["render",f]]);export{P as __pageData,w as default};
